// 1. File Access: Opening and Data Transfer (via syscalls)

int fd = open("device.log", O_WRONLY | O_APPEND, 0600);
char data[] = "Log entry.\n";

// System call to write data (requires kernel mediation)
if (fd >= 0) {
    ssize_t bytes_written = write(fd, data, sizeof(data) - 1);

    // Check for ECF/error states
    if (bytes_written < 0) {
        perror("Write failed");
    }
    close(fd);
} else {
    // ECF: Open failure (permissions, path not found)
    perror("Open failed");
}


// 2. Hardware Position Control (lseek)

int fd_data = open("binary.dat", O_RDONLY);
off_t offset;

// Reposition the file pointer using syscall
offset = lseek(fd_data, 1024, SEEK_SET);

// ECF: Kernel error during seek
if (offset == (off_t)-1) {
    // Handle error (e.g., file not seekable)
    close(fd_data);
}

// Read from the new position
char buffer[32];
read(fd_data, buffer, 32);


// 3. ECF: Handling Signals (Software Interrupts)

// Handler function triggered by ECF (signal)
void handle_sigterm(int signum) {
    if (signum == SIGTERM) {
        cleanup_resources();
        _exit(1); // Use safe syscall exit
    }
}

// Register the handler
struct sigaction sa;
sa.sa_handler = handle_sigterm;
sigemptyset(&sa.sa_mask);
sa.sa_flags = 0;

sigaction(SIGTERM, &sa, NULL);
// Program flow interrupted when SIGTERM is delivered
